import{_ as e,c as i,o as l,af as r}from"./chunks/framework.BKeRpnBD.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"易經人生導航","text":"用 AI 解讀卦象，用原典理解變化","tagline":"起卦、解卦、讀經典、學六十四卦，把《易經》變成日常可用的智慧工具。","image":{"src":"/IChingStudy.png","alt":"I Ching: Yi Jing Life Guide App"}},"features":[{"title":"AI 解卦與追問","details":"圍繞你的問題解讀卦象、動爻與變化方向，幫助你整理決策、關係、時機與內在處境。"},{"title":"易經原典閱讀","details":"集中閱讀《周易》、易傳、周易正義、高島易斷、焦氏易林等典籍，支援沉浸式閱讀與繁簡切換。"},{"title":"4096 變化關係","details":"探索 64×64 種本卦到之卦的變化網路，看見動爻如何改變局勢，而不只停留在單次結果。"},{"title":"課程與測驗","details":"用結構化課程、卦名練習、卦辭與爻辭測驗，把零散認識逐步變成穩定理解。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),t={name:"index.md"};function n(o,a,s,h,p,d){return l(),i("div",null,[...a[0]||(a[0]=[r('<h2 id="不只是占卦-更是一套易學系統" tabindex="-1">不只是占卦，更是一套易學系統 <a class="header-anchor" href="#不只是占卦-更是一套易學系統" aria-label="Permalink to “不只是占卦，更是一套易學系統”">​</a></h2><p>《I Ching: Yi Jing Life Guide》將易經占問、AI 解讀、古籍閱讀、卦象學習、變化網路、課程與測驗放在同一個 App 裡。你可以在遇到問題時快速起卦，也可以長期研讀《周易》與重要易學典籍，逐步建立自己的判斷力。</p><p>如果你搜尋的是「易經 App」、「周易學習」、「六十四卦查詢」、「AI 解卦」、「I Ching app」或「Book of Changes」，這款 App 的設計目標不是給你一句神祕答案，而是讓你看見卦象背後的結構、語境與可行方向。</p><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to “核心功能”">​</a></h2><ul><li><strong>AI 卦象解讀</strong>：輸入你的問題，從卦義、動爻、之卦與現實處境多角度理解。</li><li><strong>多種起卦方式</strong>：支援大衍、銅錢、一爻成卦、高島略筮等練習方式。</li><li><strong>古籍典藏閱讀</strong>：閱讀常用易學典籍，支援閱讀進度保存、字號、排版、文字顏色與繁簡切換。</li><li><strong>六十四卦學習</strong>：查詢卦辭、象辭、爻辭與卦象結構，理解每一卦如何成立。</li><li><strong>4096 變化網路</strong>：查看本卦到之卦的完整變化關係，快速定位動爻與轉化模式。</li><li><strong>課程、測驗、收藏與筆記</strong>：用長期學習方式掌握易經，不只依賴單次占問。</li></ul><h2 id="適合誰使用" tabindex="-1">適合誰使用？ <a class="header-anchor" href="#適合誰使用" aria-label="Permalink to “適合誰使用？”">​</a></h2><ul><li>想用《易經》輔助自我反思與決策的人</li><li>想系統學習六十四卦、卦辭、爻辭的人</li><li>想閱讀易學原典與後世注解的人</li><li>想把 AI 解讀作為學習工具，而不是迷信答案的人</li><li>想建立長期易學筆記與收藏系統的人</li></ul><h2 id="常見問題" tabindex="-1">常見問題 <a class="header-anchor" href="#常見問題" aria-label="Permalink to “常見問題”">​</a></h2><h3 id="這是占卜-app-嗎" tabindex="-1">這是占卜 App 嗎？ <a class="header-anchor" href="#這是占卜-app-嗎" aria-label="Permalink to “這是占卜 App 嗎？”">​</a></h3><p>它可以起卦與解卦，但定位不只是占卜。它更像一個「易經學習與思考工具」，幫助你從卦象、原典和變化關係中整理問題。</p><h3 id="初學者能用嗎" tabindex="-1">初學者能用嗎？ <a class="header-anchor" href="#初學者能用嗎" aria-label="Permalink to “初學者能用嗎？”">​</a></h3><p>可以。App 提供 AI 解釋、課程、測驗和卦象查詢，適合從零開始理解六十四卦。</p><h3 id="進階學習者能用嗎" tabindex="-1">進階學習者能用嗎？ <a class="header-anchor" href="#進階學習者能用嗎" aria-label="Permalink to “進階學習者能用嗎？”">​</a></h3><p>可以。原典閱讀、4096 變化關係、焦氏易林與高島易斷等內容，更適合長期研讀與對照。</p><h3 id="會保存我的問題嗎" tabindex="-1">會保存我的問題嗎？ <a class="header-anchor" href="#會保存我的問題嗎" aria-label="Permalink to “會保存我的問題嗎？”">​</a></h3><p>App 強調專注學習與個人反思。你可以在 App 內保存自己的收藏、筆記和閱讀進度。</p><h2 id="下載" tabindex="-1">下載 <a class="header-anchor" href="#下載" aria-label="Permalink to “下載”">​</a></h2><p>在 App Store 下載 <strong>I Ching: Yi Jing Life Guide</strong>，把《易經》變成可以每天學習、查詢與反思的工具。</p>',18)])])}const f=e(t,[["render",n]]);export{g as __pageData,f as default};
